    {
      "registryType": "npm",
      "identifier": "@formio/uag",
      "version": "1.12.2",
      "transport": {
        "type": "streamable-http",
        "url": "http://localhost:{PORT}/mcp"
      },
      "environmentVariables": [
        {
          "name": "PROJECT",
          "description": "API endpoint to Enterprise project or OSS server",
          "isRequired": true,
          "format": "string",
          "isSecret": false
        },
        {
          "name": "PROJECT_KEY",
